final class PortalPrincipalReadModel {
    public const VERSION='portal_principal_v1';
    public function fromPrincipal(array $principal):array { foreach(array('kind','id','uid','display_reference','linked_at') as$key){if(!array_key_exists($key,$principal))throw new \InvalidArgumentException('portal_principal_unresolved');}$out=array('version'=>self::VERSION,'principal_kind'=>(string)$principal['kind'],'principal_id'=>(int)$principal['id'],'principal_uid'=>(string)$principal['uid'],'display_reference'=>(string)$principal['display_reference'],'linked_at'=>(string)$principal['linked_at']);if((string)$principal['kind']==='guardian'){foreach(array('grant_scope','grant_effective_from','grant_effective_until') as$key){if(!array_key_exists($key,$principal))throw new \InvalidArgumentException('portal_principal_unresolved');$out[$key]=$principal[$key];}}return$out; }
}

/** Internal composition seam only; controllers/routes remain deliberately absent in Phase W. */
final class PortalInternalReadSurface {
    public function studentLesson(AuthenticatedPortalReadSubject $subject,int $lessonId,?CanonicalLessonSchedulePortalReadPort $schedulePort=null):array { $schedule=($schedulePort??PortalOwnerPorts::schedule())->forSubject($subject,$lessonId);$assignment=PortalOwnerPorts::assignment()->forSubject($subject,(int)$schedule['enrolment_id']);$delivery=PortalOwnerPorts::delivery()->summaryForSubject($subject,$lessonId);$attendance=PortalOwnerPorts::attendance()->summaryForSubject($subject,$lessonId,(int)$schedule['schedule_version_id']);return(new PortalStudentLessonReadModel())->fromOwner(array_merge($schedule,$assignment,$delivery,$attendance,$this->capabilityAvailability($lessonId,(int)$schedule['schedule_version_id'],(int)$subject->principalId))); }
    public function teacherLesson(AuthenticatedPortalReadSubject $subject,int $lessonId,?CanonicalLessonSchedulePortalReadPort $schedulePort=null):array { $schedule=($schedulePort??PortalOwnerPorts::schedule())->forSubject($subject,$lessonId);$assignment=PortalOwnerPorts::assignment()->forSubject($subject,(int)$schedule['enrolment_id']);$delivery=PortalOwnerPorts::delivery()->summaryForSubject($subject,$lessonId);$attendance=PortalOwnerPorts::attendance()->summaryForSubject($subject,$lessonId,(int)$schedule['schedule_version_id']);return(new PortalTeacherLessonReadModel())->fromOwner(array_merge($schedule,$assignment,$delivery,$attendance,$this->capabilityAvailability($lessonId,(int)$schedule['schedule_version_id'],null))); }
    public function teacherAssignment(AuthenticatedPortalReadSubject $subject,int $enrolmentId,?TeacherAssignmentPortalReadPort $assignmentPort=null):array{return(new PortalTeacherAssignmentReadModel())->fromOwner(($assignmentPort??PortalOwnerPorts::assignment())->forSubject($subject,$enrolmentId));}
    public function studentEnrolment(AuthenticatedPortalReadSubject $subject,int $enrolmentId,?StudentEnrolmentPortalReadPort $enrolmentPort=null):array{return(new PortalStudentEnrolmentReadModel())->fromOwner(($enrolmentPort??new \Delnavazan\Platform\Core\Application\CanonicalStudentEnrolmentPortalReadPort())->forSubject($subject,$enrolmentId));}
    public function principal(array $principal):array{return(new PortalPrincipalReadModel())->fromPrincipal($principal);}
    private function capabilityAvailability(int $lessonId,int $scheduleVersionId,?int $studentId):array {
        $available=array(PortalRule::JOIN=>false,PortalRule::ABSENCE=>false);
        global $wpdb;
        $p=$wpdb->prefix.'dzn_portal_public_capabilities';
        $mappingTable=$wpdb->prefix.'dzn_provider_calendar_event_mappings';
        $secretTable=$wpdb->prefix.'dzn_provider_projection_secrets';
        $providerJoin=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$mappingTable} m INNER JOIN {$secretTable} s ON s.mapping_kind='calendar_event' AND s.mapping_id=m.id AND s.state='active' AND s.active_slot=1 WHERE m.lesson_id=%d AND m.schedule_version_id=%d AND m.provider_code='google_calendar' AND m.projection_state='verified' AND m.active_slot=1",$lessonId,$scheduleVersionId))===1;
        if($studentId===null){
            return array('join_available'=>$providerJoin,'join_refusal_reason'=>$providerJoin?null:'portal_capability_unknown','absence_available'=>false,'absence_refusal_reason'=>'portal_capability_unknown');
        }
        $where='lesson_id=%d AND schedule_version_id=%d AND state=\'active\' AND expires_at>UTC_TIMESTAMP() AND (subject_student_id IS NULL OR subject_student_id=%d)';
        $rows=$wpdb->get_results($wpdb->prepare("SELECT purpose FROM {$p} WHERE {$where}",array($lessonId,$scheduleVersionId,$studentId)));
        foreach((array)$rows as$row)if(isset($available[(string)$row->purpose]))$available[(string)$row->purpose]=true;
        // An authenticated Student may open the same verified provider event as the Teacher
        // without minting a public capability. Public capabilities remain the only route for
        // unauthenticated actions.
        $join=$available[PortalRule::JOIN]||$providerJoin;
        return array('join_available'=>$join,'join_refusal_reason'=>$join?null:'portal_capability_unknown','absence_available'=>$available[PortalRule::ABSENCE],'absence_refusal_reason'=>$available[PortalRule::ABSENCE]?null:'portal_capability_unknown');
    }
}
